"""All Nodes Distance K in Binary Tree — add parent links, then BFS.

With parent pointers the tree becomes an undirected graph and "distance k" is a
plain breadth-first ring.

Time: O(n)   Space: O(n)
"""
from collections import deque
from typing import List

if "TreeNode" not in globals():
    class TreeNode:
        def __init__(self, val=0, left=None, right=None):
            self.val = val
            self.left = left
            self.right = right


class Solution:
    def distanceK(self, root, target, k: int) -> List[int]:
        parents = {}

        def link(node, parent) -> None:
            if not node:
                return
            parents[node] = parent
            link(node.left, node)
            link(node.right, node)

        link(root, None)

        seen = {target}
        queue = deque([target])
        for _ in range(k):
            for _ in range(len(queue)):
                node = queue.popleft()
                for nxt in (node.left, node.right, parents[node]):
                    if nxt and nxt not in seen:
                        seen.add(nxt)
                        queue.append(nxt)
        return [node.val for node in queue]
